alter table public.profiles add column if not exists banner_url text, add column if not exists banner_motion text not null default 'none';
create table if not exists public.badges(id uuid primary key default gen_random_uuid(),slug text unique not null,name text not null,description text not null default '',icon text not null default '◆',created_at timestamptz not null default now());
create table if not exists public.profile_badges(id uuid primary key default gen_random_uuid(),user_id uuid not null references public.profiles(id) on delete cascade,badge_id uuid not null references public.badges(id) on delete cascade,granted_by uuid references public.profiles(id),granted_at timestamptz not null default now(),unique(user_id,badge_id));
create table if not exists public.profile_comments(id uuid primary key default gen_random_uuid(),profile_id uuid not null references public.profiles(id) on delete cascade,author_id uuid not null references public.profiles(id) on delete cascade,body text not null check(char_length(body) between 1 and 500),created_at timestamptz not null default now());
create table if not exists public.site_settings(id boolean primary key default true check(id),maintenance_mode boolean not null default false,nav_order text[] not null default array['/','/rules','/announcements','/members','/penalties','/control','/budget'],announcement_categories text[] not null default array['DUYURU','KARAR'],updated_by uuid references public.profiles(id),updated_at timestamptz not null default now());insert into public.site_settings(id) values(true) on conflict(id) do nothing;
alter table public.badges enable row level security;alter table public.profile_badges enable row level security;alter table public.profile_comments enable row level security;alter table public.site_settings enable row level security;
drop policy if exists "badges readable" on public.badges;create policy "badges readable" on public.badges for select using(true);
drop policy if exists "profile badges readable" on public.profile_badges;create policy "profile badges readable" on public.profile_badges for select using(true);
drop policy if exists "comments readable" on public.profile_comments;create policy "comments readable" on public.profile_comments for select using(true);
drop policy if exists "members create comments" on public.profile_comments;create policy "members create comments" on public.profile_comments for insert to authenticated with check(author_id=(select auth.uid()) and profile_id<>(select auth.uid()));
drop policy if exists "settings readable" on public.site_settings;create policy "settings readable" on public.site_settings for select using(true);
insert into public.badges(slug,name,description,icon) values('founding-member','Kurucu Dönem','Q-GANG’ın kuruluş dönemine ait kazanım.','◆'),('veteran','Kıdem','Toplulukta süreklilik ve katkı kazanımı.','✦'),('contributor','Katkı','Q-GANG’a belirgin katkı sağlayan üyeler için.','◇') on conflict(slug) do nothing;